package store

import (
	"bytes"
	"strings"
	"testing"
)

func TestSave(t *testing.T) {
	entries := []Entry{
		{Key: "a", Value: "1", TTL: 10},
		{Key: "b", Value: "2", TTL: 20},
	}

	var buf bytes.Buffer
	if err := Save(&buf, entries); err != nil {
		t.Fatalf("Save returned error: %v", err)
	}

	lines := strings.Split(strings.TrimRight(buf.String(), "\n"), "\n")
	if len(lines) != len(entries) {
		t.Fatalf("got %d lines, want %d", len(lines), len(entries))
	}

	for i, line := range lines {
		if !strings.Contains(line, entries[i].Key) {
			t.Errorf("line %d = %q, want it to contain key %q", i, line, entries[i].Key)
		}
	}
}

