package store

import (
	"encoding/json"
	"io"
)

// Load reads entries written by Save (newline-delimited JSON, one object per line).
func Load(r io.Reader) ([]Entry, error) {
	dec := json.NewDecoder(r)
	var entries []Entry
	for {
		var e Entry
		if err := dec.Decode(&e); err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
		entries = append(entries, e)
	}
	return entries, nil
}

